  "purpose": "依据本次读取到的历史助手输出中的算术不一致（实收资本小计109,500与明细行合计120,500不符），补充交叉验算检查与强制失败处理，避免未来凭证交付出现同类汇总错误。",
  "arguments": {
    "graph": {
      "base_version": 2,
      "nodes": [],
      "edges": []
    },
    "workflows": [
      {
        "workflow_id": "conv_948cdaa668ef_w1",
        "base_version": 1,
        "patch": {
          "checks": [
            "凭证总数等于日记账交易笔数",
            "每张凭证借方总额 = 贷方总额",
            "利息收入全部以负数冲减财务费用—手续费，且每笔利息收入对应银行存款与财务费用—手续费一正一负金额相等",
            "所有小计/汇总数必须等于其对应明细行金额之和（交叉验算）"
          ],
          "failure_handling": [
            "若同一日记账存在多个版本且交易不一致，默认以用户本次上传的最新文件为准，并在交付时列出差异供用户确认，不擅自合并",
            "若交叉验算发现任何小计与明细行之和不等，则停止输出并报告不一致位置，不得直接交付"
          ]
        }
      }
    ]
  }
}

